const SK = $env.SUPABASE_SERVICE_ROLE_KEY;
const SUPA = '${NEXT_PUBLIC_SUPABASE_URL}';
const h = { apikey: SK, Authorization: 'Bearer ' + SK };
const TYPE_AGENT = { task:'builder', bug:'builder', feature:'po', epic:null, ops:'ops', research:'scout', review:'tester' };
const issues = await helpers.httpRequest({
  method: 'GET',
  url: SUPA + '/rest/v1/issues?status=in.(open,in_progress,code_review,product_review,approved,released,completed)&assignee=in.(main,KAOS,kaos-claude)&type=neq.epic&select=id,task_key,title,type,assignee,status',
  headers: h
});
if (!Array.isArray(issues) || !issues.length) return [{ json: { action:'idle', checked:0 } }];
const results=[];
for (const issue of issues) {
  const correctAgent = TYPE_AGENT[issue.type];
  if (!correctAgent) continue;
  await helpers.httpRequest({
    method: 'PATCH',
    url: SUPA + '/rest/v1/issues?id=eq.' + issue.id,
    headers: { ...h, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
    body: { assignee: correctAgent }
  });
  results.push({ task_key: issue.task_key, from: issue.assignee, to: correctAgent, status: issue.status });
}
return [{ json: { action:'rerouted', count: results.length, results } }];
